#include <iostream>
int main() {
    int distance;
    std::cin >> distance;
    if (distance <= 0) { std::cout << "invalid\n"; return 0; }
    int cost = 100;
    if (distance > 5) cost += (distance - 5) * 20;
    std::cout << cost << '\n';
}
